#include <stdio.h>
int main() {
    int n1, n2; if (scanf("%d %d", &n1, &n2) != 2) return 0;
    long long a1[100005], a2[100005];
    for (int i = 0; i < n1; i++) scanf("%lld", &a1[i]);
    for (int i = 0; i < n2; i++) scanf("%lld", &a2[i]);
    int i = 0, j = 0, first = 1;
    while (i < n1 && j < n2) {
        if (a1[i] < a2[j]) {
            if (!first) putchar(' ');
            printf("%lld", a1[i]); first = 0; i++;
        } else if (a1[i] == a2[j]) { i++; }
        else { j++; }
    }
    while (i < n1) {
        if (!first) putchar(' ');
        printf("%lld", a1[i++]); first = 0;
    }
    printf("\n");
    return 0;
}

