#include <iostream>
#include <vector>
#include <unordered_set>
using namespace std;
int main() {
    int n1, n2; if (!(cin >> n1 >> n2)) return 0;
    vector<long long> a1(n1);
    for (int i = 0; i < n1; i++) cin >> a1[i];
    unordered_set<long long> s2;
    for (int i = 0; i < n2; i++) { long long x; cin >> x; s2.insert(x); }
    bool first = true;
    for (long long x : a1) {
        if (!s2.count(x)) {
            if (!first) cout << " ";
            cout << x; first = false;
        }
    }
    cout << "\n";
    return 0;
}

code.Java:
import java.util.Scanner;
import java.util.HashSet;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNextInt()) {
            int n1 = sc.nextInt(), n2 = sc.nextInt();
            long[] a1 = new long[n1];
            for (int i = 0; i < n1; i++) a1[i] = sc.nextLong();
            HashSet<Long> s2 = new HashSet<>();
            for (int i = 0; i < n2; i++) s2.add(sc.nextLong());
            StringBuilder sb = new StringBuilder();
            for (long x : a1) {
                if (!s2.contains(x)) {
                    if (sb.length() > 0) sb.append(" ");
                    sb.append(x);
                }
            }
            System.out.println(sb.toString());
        }
    }
}

