const fs = require("fs");
function main() {
    const toks = fs.readFileSync(0, "utf-8").trim().split(/\s+/);
    if (toks.length >= 2) {
        const n1 = parseInt(toks[0], 10), n2 = parseInt(toks[1], 10);
        const a1 = toks.slice(2, n1 + 2);
        const s2 = new Set(toks.slice(n1 + 2, n1 + n2 + 2));
        const res = a1.filter(x => !s2.has(x));
        console.log(res.join(" "));
    }
}
main();

